{"cards": [{"node_code": "N_526f986fc3bd755c", "definition": "研究钢构件在工厂或现场的制作与加工工艺，涵盖下料、成型、焊接、钻孔、防腐涂装及质量检验，确保构件符合设计尺寸与性能要求。", "boundary": "本节点聚焦于钢构件从原材料到成品的制造过程，包括切割、弯曲、焊接、组装及表面处理。边界涵盖传统加工与自动化制造技术。不包含现场吊装、安装及连接施工（归入钢结构安装与校正或连接施工），也不包含结构设计计算。", "includes": ["钢构件下料、成型、焊接、钻孔及组装工艺", "钢构件防腐、防火涂装及表面预处理技术", "钢构件加工过程中的质量控制与检测"], "excludes": ["钢构件的现场吊装、安装及校正（归入钢结构安装与校正）", "钢构件的现场连接施工（归入钢结构连接施工）", "钢结构的设计计算与力学分析（归入建筑与结构工程）"], "sibling_distinctions": [{"other_code": "N_32d4be14131b9c8d", "rule": "本节点关注构件在工厂或现场的“制造”过程；兄弟节点关注构件在工程现场的“安装”与“校正”过程。"}, {"other_code": "N_6da21756285942b7", "rule": "本节点关注构件整体的制作与加工；兄弟节点关注构件之间或构件与基础之间的“连接”施工细节。"}], "cross_boundary_rule": "钢构件的工厂预制与加工归入本节点；若涉及构件在现场的临时固定、永久连接或整体校正，归入钢结构安装与校正或钢结构连接施工。"}, {"node_code": "N_32d4be14131b9c8d", "definition": "研究钢结构在工程现场的吊装、定位、临时固定、永久连接及整体校正技术，确保结构几何精度与受力状态符合设计要求。", "boundary": "本节点聚焦于钢结构从构件就位到整体成型的过程，包括吊装方案、安装顺序、临时支撑、螺栓/焊接连接及精度校正。边界涵盖大型复杂钢结构的安装工艺。不包含构件的工厂制作（归入钢构件制作与加工）或纯结构设计。", "includes": ["钢结构吊装方案、安装顺序及临时支撑技术", "钢构件现场定位、临时固定及永久连接施工", "钢结构整体精度校正、变形监测及调整技术"], "excludes": ["钢构件的工厂制作与加工（归入钢构件制作与加工）", "装配式混凝土构件的吊装与安装（归入装配式构件吊装与安装）", "钢结构的设计计算与力学分析（归入建筑与结构工程）"], "sibling_distinctions": [{"other_code": "N_526f986fc3bd755c", "rule": "本节点关注构件在工程现场的“安装”与“校正”；兄弟节点关注构件在工厂或现场的“制作”与“加工”。"}, {"other_code": "N_d756fae7798fb698", "rule": "本节点特指“钢结构”的安装与校正；兄弟节点“结构吊装与安装”范围更广，可能包含其他类型结构或更通用的吊装技术。"}, {"other_code": "N_6da21756285942b7", "rule": "本节点涵盖安装全过程，包括连接；兄弟节点“钢结构连接施工”更聚焦于连接节点本身的工艺细节。"}], "cross_boundary_rule": "钢结构安装过程中的连接施工若作为安装环节的一部分，归入本节点；若专门研究连接节点工艺、材料或检测，可归入钢结构连接施工。"}, {"node_code": "N_d756fae7798fb698", "definition": "研究各类工程结构（含钢、混凝土、组合等）的吊装工艺、安装方法及现场定位技术，涵盖吊装设备选择、吊点设计及安装顺序优化。", "boundary": "本节点聚焦于结构构件的“吊装”与“安装”通用技术，包括吊装力学分析、设备选型、吊点计算及安装工艺。边界涵盖大型构件、复杂结构的吊装方案。不包含构件制作（归入钢构件制作与加工）或纯结构设计。", "includes": ["结构构件吊装方案、吊点设计及吊装设备选型", "结构构件现场安装方法、定位技术及安装顺序优化", "吊装过程中的安全监测、变形控制及应急处理"], "excludes": ["钢构件的工厂制作与加工（归入钢构件制作与加工）", "钢结构安装后的整体校正与精度调整（归入钢结构安装与校正）", "结构的设计计算与力学分析（归入建筑与结构工程）"], "sibling_distinctions": [{"other_code": "N_32d4be14131b9c8d", "rule": "本节点关注“吊装”与“安装”的通用技术；兄弟节点“钢结构安装与校正”更聚焦于钢结构特有的安装工艺及校正技术。"}, {"other_code": "N_526f986fc3bd755c", "rule": "本节点关注构件的“吊装”与“安装”；兄弟节点关注构件的“制作”与“加工”。"}], "cross_boundary_rule": "通用结构吊装技术归入本节点；若专门针对钢结构安装后的校正、精度调整，归入钢结构安装与校正。"}]}
